using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class WorkflowRevisionTests
{
 class User(bool allowed=true):ICurrentUser{public string Email=>"workflow@example.local";public int? EmployeeId=>6;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>allowed;public bool Can(string p)=>allowed;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static WorkflowService S(AppDbContext d,bool allowed=true){var u=new User(allowed);return new(d,u,new(d,u,new(TimeProvider.System)));}
 [Fact]public async Task SameDefinitionReusesHashAndLaterEditCannotRewriteOldRoute(){await using var d=await Db();var s=S(d);var e=(await d.Set<Employee>().FindAsync(6))!;var first=new LeaveRequest();await s.RouteRequestAsync("Leave",first,e,1);await d.SaveAsync();var hash=first.WorkflowRevisionHash;var route=first.Route;var second=new LeaveRequest();await s.RouteRequestAsync("Leave",second,e,5);await d.SaveAsync();Assert.Equal(hash,second.WorkflowRevisionHash);Assert.Single(await d.Set<WorkflowRevision>().ToListAsync());await s.AddStepAsync("Leave",ApproverType.Role,[Roles.FinanceManager],null);var third=new LeaveRequest();await s.RouteRequestAsync("Leave",third,e,1);await d.SaveAsync();Assert.NotEqual(hash,third.WorkflowRevisionHash);Assert.Equal(hash,first.WorkflowRevisionHash);Assert.Equal(route,first.Route);Assert.Equal(2,await d.Set<WorkflowRevision>().CountAsync());}
 [Fact]public async Task RevisionsAreAppendOnlyAndListRequiresPermission(){await using var d=await Db();var s=S(d);var e=(await d.Set<Employee>().FindAsync(6))!;await s.RouteRequestAsync("Correction",new AttendanceCorrection(),e,0);await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,false).RevisionsAsync());var r=await d.Set<WorkflowRevision>().SingleAsync();r.DefinitionJson="changed";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task NewLeavePersistsRevisionButLegacyRemainsUnknown(){await using var d=await Db();var u=new User();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var s=new LeaveService(d,new(d,u),u,a,new(d,u,c),c,S(d));var day=c.Today.AddDays(14);while(day.DayOfWeek is DayOfWeek.Friday or DayOfWeek.Saturday)day=day.AddDays(1);d.Set<LeaveRequest>().RemoveRange(await d.Set<LeaveRequest>().Where(x=>x.EmployeeId==6).ToListAsync());await d.SaveAsync();var t=await d.Set<LeaveType>().FirstAsync(x=>!x.RequiresDocument);await s.RequestAsync(t.Id,day,day,"Revision test",null);var r=await d.Set<LeaveRequest>().SingleAsync(x=>x.EmployeeId==6);Assert.NotNull(r.WorkflowRevisionHash);Assert.Contains(await S(d).RevisionsAsync(),v=>v.Hash==r.WorkflowRevisionHash);Assert.Null(new LeaveRequest().WorkflowRevisionHash);}
}
